        emon.Port.Cells t5e = emon.Port.NewCells();
        emon.Port.Cells t6e = emon.Port.NewCells();
        emon.Port.Cells t7e = emon.Port.NewCells();
        emon.Port.Cells t8e = emon.Port.NewCells();
